-- 마스터 시드(ROADMAP T-07). 실제 공공데이터 API 인증키가 없어 합성 데이터로 생성했다.
-- 약국 상호·주소는 가상이며 실존 업체와 무관하다.
-- 각 테이블의 자연키(region.code, pharmacy.hira_code, drug.item_seq, app_user.email)에
-- ON CONFLICT DO NOTHING을 걸어 재실행해도 중복이 생기지 않는다(ROADMAP T-07 완료 판정).
-- id를 직접 지정하므로(BIGSERIAL은 SERIAL 컬럼이라 명시적 insert가 그대로 된다) 파일 끝에서 시퀀스를 맞춘다.

-- region
ON CONFLICT (code) DO NOTHING;

-- pharmacy
ON CONFLICT (hira_code) DO NOTHING;

-- drug
ON CONFLICT (item_seq) DO NOTHING;

-- app_user (관리자 1 + 더미 제보자 20명)
ON CONFLICT (email) DO NOTHING;

-- BIGSERIAL 컬럼에 id를 직접 넣었으니 다음 nextval()이 겹치지 않게 시퀀스를 맞춘다.
SELECT setval(pg_get_serial_sequence('pharmacy', 'id'), (SELECT MAX(id) FROM pharmacy));
SELECT setval(pg_get_serial_sequence('drug', 'id'), (SELECT MAX(id) FROM drug));
SELECT setval(pg_get_serial_sequence('app_user', 'id'), (SELECT MAX(id) FROM app_user));
